2	// of a silent `if (res.ok)` that leaves the UI showing stale data.
3	async function send<T>(path: string, init?: RequestInit): Promise<T> {
4	  const res = await fetch(path, init);
5	  if (!res.ok) {
6	    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
7	  }
8	  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
9	}
10	
11	export function getJson<T>(path: string): Promise<T> {
12	  return send<T>(path);
13	}
14	
15	export function postJson<T>(path: string, body: unknown): Promise<T> {
16	  return send<T>(path, {
17	    method: 'POST',
18	    headers: { 'Content-Type': 'application/json' },
19	    body: JSON.stringify(body),
20	  });
